<template><section class="ops-panel"><h2>本人身份恢复码</h2><template v-if="!identityPolicyAvailable"><p class="ops-muted">{{ identityPolicyNotice }}</p><el-button v-if="identityPolicyError" type="text" :loading="identityPolicyLoading" @click="loadIdentityPolicy">重试</el-button></template><template v-else><p class="ops-muted">恢复码用于丢失验证器时申请身份恢复。重新生成会使旧恢复码失效，请私下妥善保存。</p><el-button size="small" @click="open">生成恢复码</el-button><el-dialog title="生成本人恢复码" :visible.sync="visible" width="min(520px,94vw)" :close-on-click-modal="false" @closed="clear"><template v-if="code"><el-alert title="仅本次显示。请保存到自己的密码管理器，不要交给其他员工。" type="warning" :closable="false" /><pre class="recovery-code">{{ code }}</pre></template><el-form v-else label-width="100px"><el-form-item label="当前密码"><el-input v-model="password" type="password" autocomplete="current-password" /></el-form-item><el-form-item label="动态验证码"><el-input v-model="otpCode" maxlength="6" autocomplete="one-time-code" placeholder="刚登录时请等验证器下一次刷新" /></el-form-item><el-form-item label="图形验证码"><div class="ops-captcha"><el-input v-model="captchaValue" maxlength="8" /><button type="button" @click="captcha"><img v-if="captchaUrl" :src="captchaUrl" alt="刷新验证码" /></button></div></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" :closable="false" /><span slot="footer"><el-button @click="visible=false">关闭</el-button><el-button v-if="!code" type="primary" :loading="busy" @click="submit">生成并替换恢复码</el-button></span></el-dialog></template></section></template>
<script>
import Api from '@/apis/api';
import { platformRequest } from '@/apis/platform';
import { getUUID,sm2Encrypt } from '@/utils';
import identityPolicyState from './identityPolicyState';
export default {mixins:[identityPolicyState],created(){this.loadIdentityPolicy();},data(){return{visible:false,password:'',otpCode:'',captchaValue:'',captchaId:'',captchaUrl:'',code:'',error:'',busy:false};},beforeDestroy(){this.clear();},methods:{open(){if(!this.identityPolicyAvailable)return;this.clear();this.visible=true;this.$store.dispatch('fetchPubConfig');this.captcha();},clear(){this.password='';this.otpCode='';this.code='';this.error='';if(this.captchaUrl)URL.revokeObjectURL(this.captchaUrl);this.captchaUrl='';},captcha(){this.captchaId=getUUID();this.captchaValue='';Api.user.getCaptcha(this.captchaId,response=>{if(this.captchaUrl)URL.revokeObjectURL(this.captchaUrl);this.captchaUrl=URL.createObjectURL(response.data);});},async submit(){if(this.busy)return;if(!this.identityPolicyAvailable){this.error=this.identityPolicyNotice;return;}if(!this.password||!/^\d{6}$/.test(this.otpCode)||!this.captchaValue){this.error='请填写密码和验证码';return;}this.busy=true;this.error='';try{const result=await platformRequest('POST','/ops/auth/recovery-code',{username:this.$store.state.userInfo.username,password:sm2Encrypt(this.$store.state.pubConfig.sm2PublicKey,this.captchaValue+this.password),captchaId:this.captchaId,otpCode:this.otpCode});this.code=result.recoveryCode;this.password='';this.otpCode='';}catch(error){this.error=error.message;this.captcha();}finally{this.busy=false;}}}};
</script>
<style scoped>.recovery-code{padding:20px;background:#edf3f8;white-space:pre-wrap;overflow-wrap:anywhere;user-select:all}</style>
